import { edit_project_details } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    projectEdition: Boolean,
    projectitems: Object,
    activityData: Array
  },
  data() {
    return {
      ProjectName: "",
      loading: false,
      projectActivity: ""
    };
  },
  watch: {
    projectEdition: {
      async handler() {
        // console.log(this.projectitems);
        this.ProjectName = this.projectitems.project_name;
        this.projectActivity = this.projectitems.project_activities == undefined ? "" : this.projectitems.project_activities;
      },
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    async validate_data() {
      const {
        valid
      } = await this.$refs.form.validate();
      if (valid) {
        await this.edit_event_info();
      }
    },
    async edit_event_info() {
      this.loading = true;
      try {
        let result = await API.graphql(graphqlOperation(edit_project_details, {
          input: {
            project_id: this.projectitems.project_id,
            project_name: this.ProjectName,
            project_activities: this.projectActivity
          }
        }));
        var response = JSON.parse(result.data.edit_project_details);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.$emit("errorMsg", error.errors[0].message);
        this.loading = false;
      }
    }
  }
};
